#!/usr/bin/env python3
"""Create the self-contained Phase86 report and machine-readable decision."""
from __future__ import annotations
import datetime as dt, hashlib, json, os, subprocess, tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'outputs/iclr27_phase86'; DOC=ROOT/'docs/iclr27_phase86/PHASE86_AUTONOMOUS_RESEARCH_REPORT.md'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1<<20),b''):h.update(b)
 return h.hexdigest()
def load(p): return json.loads(p.read_text())
def atom(p,v):
 p.parent.mkdir(parents=True,exist_ok=True);fd,t=tempfile.mkstemp(prefix='.'+p.name+'.',dir=str(p.parent))
 try:
  with os.fdopen(fd,'w') as f:json.dump(v,f,indent=2,sort_keys=True,allow_nan=False);f.write('\n');f.flush();os.fsync(f.fileno())
  os.replace(t,p)
 finally:
  if os.path.exists(t):os.unlink(t)
def main():
 reg=load(OUT/'audit/window_registration.json'); ctrl=load(OUT/'manifests/frozen_controller_manifest.json'); d=load(OUT/'diagnostic_ocd/summary.json'); parity=load(OUT/'audit/controller_baseline_parity.json');u1=load(OUT/'audit/u1_decision.json');rf=load(OUT/'audit/rf_decision.json');
 u1fs=u1['train_validation_folds']; d0=d['streams']['D0_historical_Q0_RCMSOCD']['aggregate_commit_ct'];d1=d['streams']['D1_temporal_physical_RCMSOCD']['aggregate_commit_ct']; rf16=next(x['aggregate'] for x in rf['aggregate'] if x['prefix']==16); ev16=u1['formal_event_replay']
 status='PHASE86_DIAGNOSTIC_COMPLETE_U1_EVENT_SAFETY_FAIL_RF_NEGATIVE_U2_NOT_OPENED'
 decision={'schema_version':'trackocd.phase86.decision.v1','phase':86,'status':status,'diagnostic_commit_ct':{'D0':d0,'D1':d1},'u1':u1,'rf':{'decision':rf['decision'],'p16':rf16,'non_decreasing_folds':rf['p16_non_decreasing_folds']},'controller_run':False,'formal_ocd_run':False,'sealed_run':False,'public_dev_q1_sealed_accessed':False,'future_rows_or_tracks':False,'ids_or_text_as_model_input':False,'u2_opened':False,'u2_trigger':'U1 TRAIN gate failure on >=2/3 validation folds','u2_trigger_satisfied':False,'next_action':'Keep frozen evidence; no controller/sealed claim. A new U2 authorization is required before relation-encoder training because the registered U1 TRAIN trigger did not fail.'}
 atom(OUT/'audit/phase86_decision.json',decision);atom(OUT/'status.json',decision)
 lines=['# TrackOCD Phase86 — Autonomous Research Report','','## Decision','','**Status:** `'+status+'`  ','**Diagnostic label:** `DIAGNOSTIC_ONLY_DO_NOT_SELECT`  ','**Formal OCD / sealed:** not run.','',f"Window: `{reg['start_utc']}` → `{reg['deadline_utc']}` (registered ten-hour window). Start HEAD: `{reg['start_head']}`; Phase85 artifacts were read-only. Large outputs: `{reg['large_output_root']}` via the `outputs/iclr27_phase86` symlink.",'','## Frozen boundary and resources','', '- No DEV+, Q1, public-new, or sealed labels were used as model inputs or for selection. No future rows/tracks, category/text, semantic IDs, or physical IDs entered inference tensors.', '- GPU0 external PID 33785 was not touched. Phase86 diagnostic/U1/RF work was CPU-only; no task GPU worker, OOM, or external-process termination occurred. RAM was about 125 GiB total with about 113 GiB available at registration; `/data1` had about 29 GiB free and `/data2` about 1.1 TiB.', '- Phase85 and earlier files remain read-only. Failed markers and hashes are retained; artifacts are atomic where applicable.','', '## Historical frozen controller','',f"The chronology/formal-use rule selected Phase19R RC-MS-OCD plus its shared StateMemory, with checkpoint/code hashes in `{(OUT/'manifests/frozen_controller_manifest.json').resolve()}`. The selection was made before the Phase86 replay and was not performance-selected. Phase56's controller was not substituted.",'','## D0–D3 frozen diagnostic OCD','', '| stream | Commit-CT | fold distribution | status |','|---|---:|---|---|',f"| D0 historical Q0 + frozen RC-MS-OCD | {d0['correct']}/{d0['eligible']} | f0=0/12, f1=0/12, f2=0/24, f3=3/28 | diagnostic only |",f"| D1 temporal physical + frozen RC-MS-OCD | {d1['correct']}/{d1['eligible']} | f0=0/12, f1=0/12, f2=0/24, f3=3/28 | diagnostic only |",'', 'D2 raw source-conditioned support and D3 bounded reranker support were not run through the controller: their frozen Phase85 artifacts are score-level evidence, not legal causal 768-D row-vector inputs. No score calibration or invented adapter was used. The Phase86 summary and `event_traces.jsonl` are diagnostic-only. The legacy Phase72 parity comparison is explicitly `protocol_equal=false` because its JSON uses a different event-accounting representation.','', '## U1 — OOF selective intervention','', 'The frozen Phase85 raw and bounded reranker experts were not retrained. U1 used OOF TRAIN predictions only, with a fixed 64-D causal score/context feature vector, MLP `64→32→utility`, labels HELP=+1, HARM=-4, both-correct/both-wrong=0, and `utility>0` selecting reranker else exact raw. The 2,095-row meta manifest and expert/checkpoint hashes are recorded under `outputs/iclr27_phase86/manifests/`.','', '| OOF validation fold | rescue | harm | net rescue | TRAIN gate |','|---:|---:|---:|---:|---|']
 for x in u1fs: lines.append(f"| {x['fold']} | {x['rescue']} | {x['harm']} | {x['net_rescue']} | {'PASS' if x['pass'] else 'FAIL'} |")
 lines += ['', f"TRAIN gate: **{'PASS' if u1['train_gate_pass'] else 'FAIL'}** (at least 2/3 folds satisfied net rescue>0 and harm≤rescue).",'', '| p16 event replay | raw | full reranker | U1 selective | registered status |','|---|---:|---:|---:|---|',f"| positive reliable events | {ev16['positive_p16']['raw_reliable_events']}/76 | {ev16['positive_p16']['reranked_reliable_events']}/76 | {ev16['positive_p16']['u1_reliable_events']}/76 | ≥22 |",f"| negative reliable events | {ev16['negative_p16']['raw_reliable_events']}/76 | {ev16['negative_p16']['reranked_reliable_events']}/76 | {ev16['negative_p16']['u1_reliable_events']}/76 | ≤8 |",'', 'U1 event status is **FAIL**: selective intervention reaches 22/76 positives but 12/76 negatives, and uses the reranker on 58/76 negative events. Consequently no controller compatibility or Commit-CT claim was authorized. This event replay is a score-level route and does not override the U1 TRAIN trigger rule.','', '## RF — Root-of-Fragments diagnostic','', f"RF was parameter-free: fixed causal contiguous four-frame fragments from frozen Phase75D vectors, symmetric Chamfer matching, and raw + `0.05*tanh` residual. It produced p16 R@1 `{rf16['r1']:.6f}` vs raw `{rf16['raw_r1']:.6f}`, mAP `{rf16['map']:.6f}` vs raw `{rf16['raw_map']:.6f}`, hard-gap `{rf16['hard_negative_gap']:.6f}` vs raw `{rf16['raw_hard_negative_gap']:.6f}`, unsafe flips `{rf16['unsafe_flip_count']}`, and `{rf['p16_non_decreasing_folds']}/4` non-decreasing folds. Decision: **{rf['decision']}**. No training or controller run followed.",'','## Failures and repairs','', '- Diagnostic r0: import path failure; retained in `completion/diagnostic_ocd_r0_failed.json`; fixed by the minimal project-root path insertion.', '- Diagnostic r1: Phase85 artifact path resolved under Phase86 output; D0/D1 completed in memory but summary commit failed; retained in `diagnostic_ocd_r1_failed.json`; fixed by a path-only correction.', '- U1 r1 smoke: scalar/list counter initialization raised a TypeError before metrics; retained as a failed marker; fixed by typed counters and rerun with fresh tag r2. U1 smoke, targeted, and formal artifacts are separate and atomic.', '- No OOM, duplicate supervisor, broad kill, or external-process termination occurred.','', '## Gate and next-route decision','', '| gate | result | evidence |','|---|---|---|',f"| D0/D1 diagnostic | COMPLETE | 3/76 each, all fold3; diagnostic only |",f"| U1 TRAIN safety | {'PASS' if u1['train_gate_pass'] else 'FAIL'} | 2/3 OOF folds pass |",f"| U1 event safety | FAIL | 22/76 positive, 12/76 negative |",f"| RF TRAIN validation | FAIL | 2/4 non-decreasing; no safe improvement |",'| controller/formal OCD | NOT RUN | no legal safe upstream candidate |','| sealed/public | NOT RUN | sealed boundary preserved |','', 'U2 was **not opened**: the pre-registered trigger is a failed U1 TRAIN gate, while U1 TRAIN safety passed on 2/3 folds. Opening U2 solely because the event score route failed would silently change the registered route order. A future U2 requires explicit authorization or a new preregistration.','', '## Reproduction commands','', '```bash', 'cd /data1/LWR/vranlee/SERVER_ONLY/avis/OCD_OVMOT', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/discover_controller.py', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_diagnostic_ocd.py', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/validate_baseline_parity.py', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_u1_selective.py --mode smoke --tag r2 --fold 0', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_u1_selective.py --mode targeted --tag r1 --fold 0', 'for f in 0 1 2; do /home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_u1_selective.py --mode formal --tag r1 --fold "$f"; done', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_u1_event_replay.py --tag u1_formal_replay_r1', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_rf_diagnostic.py', '```','', '## Key artifacts','',f"- Report: `{DOC.resolve()}`",f"- Decision: `{(OUT/'audit/phase86_decision.json').resolve()}`",f"- Diagnostic: `{(OUT/'diagnostic_ocd/summary.json').resolve()}`",f"- U1 decision: `{(OUT/'audit/u1_decision.json').resolve()}`",f"- RF decision: `{(OUT/'audit/rf_decision.json').resolve()}`",f"- Controller manifest: `{(OUT/'manifests/frozen_controller_manifest.json').resolve()}`",'', 'The report does not claim complete MOT+OCD. Persistent Commit-CT formal and sealed evaluation remain unrun because the only registered score-level intervention failed event safety and no controller-compatible safe upstream candidate was produced.']
 DOC.parent.mkdir(parents=True,exist_ok=True);DOC.write_text('\n'.join(lines)+'\n',encoding='utf-8')
 current_head=subprocess.run(['git','rev-parse','HEAD'],cwd=ROOT,text=True,capture_output=True,check=False).stdout.strip()
 prov={'schema_version':'trackocd.phase86.report_provenance.v1','phase':86,'status':status,'generated_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'report':str(DOC.resolve()),'report_sha256':sha(DOC),'decision':str((OUT/'audit/phase86_decision.json').resolve()),'decision_sha256':sha(OUT/'audit/phase86_decision.json'),'start_head':reg['start_head'],'science_head':current_head,'report_generation_head':current_head,'final_head':current_head,'public_dev_q1_sealed_accessed':False,'formal_ocd_run':False,'sealed_run':False}
 atom(OUT/'audit/report_provenance.json',prov);print(json.dumps(prov,indent=2,sort_keys=True))
if __name__=='__main__':main()
